import com.google.gson.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.jar.*;
import java.util.zip.*;
import java.io.*;
public final class ClientJarPackager{
 static String sha(byte[]b)throws Exception{return HexFormat.of().withUpperCase().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}
 static String sha(Path p)throws Exception{var d=MessageDigest.getInstance("SHA-256");try(var in=Files.newInputStream(p)){byte[]b=new byte[1048576];for(int n;(n=in.read(b))!=-1;)d.update(b,0,n);}return HexFormat.of().withUpperCase().formatHex(d.digest());}
 static void write(ZipOutputStream z,String name,byte[]data)throws Exception{var e=new ZipEntry(name);e.setTime(0);z.putNextEntry(e);z.write(data);z.closeEntry();}
 public static void main(String[]a)throws Exception{
  Path repo=Path.of(a[0]),runtime=Path.of(a[1]),out=Path.of(a[2]),report=Path.of(a[3]);if(Files.exists(out)||Files.exists(report))throw new IllegalArgumentException("New outputs required");Files.createDirectories(out.getParent().resolve("lib"));var lock=JsonParser.parseString(Files.readString(repo.resolve("vendor/RUNTIME_DEPENDENCIES.lock.json"))).getAsJsonObject();List<JsonObject>providers=new ArrayList<>();for(var e:lock.getAsJsonArray("providers"))providers.add(e.getAsJsonObject());providers.sort(Comparator.comparingInt(x->x.get("index").getAsInt()));List<String>classPath=new ArrayList<>();JsonArray libs=new JsonArray();
  for(int i=0;i<providers.size();i++){var p=providers.get(i);if(p.get("index").getAsInt()!=i)throw new IllegalArgumentException("Provider ordering gap");Path source=repo.resolve(p.get("path").getAsString());if(!sha(source).equalsIgnoreCase(p.get("sha256").getAsString()))throw new IllegalArgumentException("Provider SHA mismatch");String name="lib/"+source.getFileName();Path dest=out.getParent().resolve(name);Files.copy(source,dest);classPath.add(name);JsonObject row=p.deepCopy();row.addProperty("delivery_path",name);libs.add(row);}
  Manifest mf=new Manifest();var attrs=mf.getMainAttributes();attrs.putValue("Manifest-Version","1.0");attrs.putValue("Main-Class","moom.iP");attrs.putValue("Class-Path",String.join(" ",classPath));attrs.putValue("OpenMoon-Artifact","source-derived-R-client");ByteArrayOutputStream manifestBytes=new ByteArrayOutputStream();mf.write(manifestBytes);
  Path resources=repo.resolve(lock.getAsJsonArray("resources").get(0).getAsJsonObject().get("path").getAsString());Map<String,byte[]>entries=new TreeMap<>();int owned=0,resourceCount=0;JsonArray resourceRows=new JsonArray();
  try(var z=new ZipFile(runtime.toFile())){for(var es=z.entries();es.hasMoreElements();){var e=es.nextElement();if(!e.getName().endsWith(".class"))throw new IllegalArgumentException("R class archive contains non-class entry");byte[]b=z.getInputStream(e).readAllBytes();if(entries.put(e.getName(),b)!=null)throw new IllegalArgumentException("Duplicate R class");owned++;}}
  try(var z=new ZipFile(resources.toFile())){for(var es=z.entries();es.hasMoreElements();){var e=es.nextElement();String original=e.getName();if(java.util.Set.of("natives/moon-native.dll","natives/moon-api-win64.dll","natives/moon-api-linux.so").contains(original))continue;String name=original.equalsIgnoreCase("META-INF/MANIFEST.MF")?"META-INF/openmoon-original/MANIFEST.MF":original;byte[]b=z.getInputStream(e).readAllBytes();if(entries.put(name,b)!=null)throw new IllegalArgumentException("Resource/owned overlap");resourceCount++;JsonObject r=new JsonObject();r.addProperty("original_entry",original);r.addProperty("delivery_entry",name);r.addProperty("sha256",sha(b));resourceRows.add(r);}}
  var policy=JsonParser.parseString(Files.readString(repo.resolve("build-tools/RuntimeProjectionContract.json"))).getAsJsonObject();if(owned!=policy.get("expected_owned_classes").getAsInt()||resourceCount!=policy.get("expected_resource_entries").getAsInt())throw new IllegalArgumentException("Delivery scope incomplete");entries.put("META-INF/MANIFEST.MF",manifestBytes.toByteArray());try(var z=new ZipOutputStream(Files.newOutputStream(out,StandardOpenOption.CREATE_NEW))){z.setLevel(6);write(z,"META-INF/MANIFEST.MF",entries.remove("META-INF/MANIFEST.MF"));for(var e:entries.entrySet())write(z,e.getKey(),e.getValue());}
  try(var z=new ZipFile(out.toFile())){for(var e:resourceRows){var r=e.getAsJsonObject();if(!sha(z.getInputStream(z.getEntry(r.get("delivery_entry").getAsString())).readAllBytes()).equals(r.get("sha256").getAsString()))throw new IllegalStateException("Resource byte mismatch");}}
  JsonObject result=new JsonObject();result.addProperty("status","packaged_uid_free_R_and_retained_original_resources_pending_packaged_JVM_verification");result.addProperty("client_archive",out.toString());result.addProperty("client_sha256",sha(out));result.addProperty("owned_classes",owned);result.addProperty("original_resources",resourceCount);result.add("excluded_legacy_resources",policy.get("excluded_resources"));result.addProperty("original_manifest_preserved","META-INF/openmoon-original/MANIFEST.MF");result.addProperty("explicit_main","moom.iP");result.add("ordered_delivery_providers",libs);result.add("resource_entry_bindings",resourceRows);result.addProperty("client_executed",false);Files.writeString(report,new GsonBuilder().setPrettyPrinting().create().toJson(result),StandardOpenOption.CREATE_NEW);System.out.println("packaged_client="+out+" sha256="+sha(out));
 }
}
